def sparseMatrixMultiply(A, B):
    # Create a dictionary to store the non-zero elements of A and B
    dictA = {(i, j): val for i, row in enumerate(A) for j, val in enumerate(row) if val != 0}
    dictB = {(i, j): val for i, row in enumerate(B) for j, val in enumerate(row) if val != 0}

    # Initialize the result matrix C
    C = [[0 for _ in range(len(B[0]))] for _ in range(len(A))]

    # Perform the multiplication
    for i in range(len(A)):
        for j in range(len(B[0])):
            for k in range(len(B)):
                if (i, k) in dictA and (k, j) in dictB:
                    C[i][j] += dictA[i, k] * dictB[k, j]

    return C

